 useEffect(()=>{if(abaSolicitada==='relacionamento'){const p=new URLSearchParams(params);p.set('aba',aba);setParams(p,{replace:true});}},[abaSolicitada,aba,params,setParams]);
 useEffect(()=>{const ctl=new AbortController();setCarregando(true);setErro('');chamarComercial('painel',{filtro:JSON.parse(chave)},ctl.signal).then(d=>{if(!ctl.signal.aborted)setCarga({chave,dados:d});}).catch(e=>{if(!ctl.signal.aborted)setErro(e.message);}).finally(()=>{if(!ctl.signal.aborted)setCarregando(false);});return()=>ctl.abort();},[chave,revisao]);
 const busca=params.get(`busca_${aba}`)||'',situacao=params.get(`situacao_${aba}`)||'';
 const setBusca=v=>{const p=new URLSearchParams(params);v?p.set(`busca_${aba}`,v):p.delete(`busca_${aba}`);setParams(p,{replace:true});};
 const setSituacao=v=>{const p=new URLSearchParams(params);v?p.set(`situacao_${aba}`,v):p.delete(`situacao_${aba}`);setParams(p,{replace:true});};
 function datasPeriodo(tipo){const d=new Date(hoje+'T12:00:00');if(tipo==='anterior')d.setMonth(d.getMonth()-1,1);const ano=d.getFullYear(),mes=String(d.getMonth()+1).padStart(2,'0');return {de:tipo==='ano'?`${ano}-01-01`:`${ano}-${mes}-01`,ate:tipo==='ano'?`${ano}-12-31`:`${ano}-${mes}-${new Date(ano,d.getMonth()+1,0).getDate()}`};}
 const periodo=tipo=>alterar(datasPeriodo(tipo));
 const periodoAtivo=tipo=>{const d=datasPeriodo(tipo);return d.de===filtro.de&&d.ate===filtro.ate;};
 const abrirAcao=a=>{const original=a?.id?dados?.base.acoes.find(x=>String(x.id)===String(a.id)):null;setModal({tipo:a?.origem==='mesa'?'legado':'acao',a:original?{...original,...a}:a});};
 const fecharModal=()=>{if(modal?.voltar){setModal(modal.voltar);return;}setModal(null);if(params.has('acao')||params.has('orcamento')){const p=new URLSearchParams(params);p.delete('acao');p.delete('orcamento');p.delete('contato');setParams(p,{replace:true});}};
