 useEffect(()=>{if(!dados)return;const id=params.get('acao'),orcId=params.get('orcamento');if(id){const a=dados.base.acoes.find(x=>String(x.id)===id);if(a)setModal({tipo:a.origem==='mesa'?'legado':'acao',a});else setErro('Atividade não localizada na carteira selecionada. Confira a vendedora e o vínculo original.');}else if(orcId){const o=dados.base.orcamentos.find(x=>String(x.id)===orcId);if(o){const a=dados.base.acoes.filter(x=>x.origem!=='mesa'&&String(x.orcamentoId)===orcId&&x.status!=='concluida').sort((a,b)=>String(a.data).localeCompare(String(b.data)))[0];setModal({tipo:'acao',a:{...a,orcamentoId:o.id,clienteId:o.clienteId,registroRapido:params.get('contato')==='1'}});}else setErro('Orçamento não localizado na carteira autorizada.');}},[dados,params]);
 const detalhe=(titulo,itens,tipo,periodo=filtro)=>setModal({tipo:'lista',titulo,itens,conteudo:tipo,periodo});
