 function abrirPedido(p){setModal({tipo:'pedido',p});}
 function linhasOs(xs){return xs.map(o=>{const sinal=o.sinalPago==null||o.sinalPago===''?null:Number(o.sinalPago),f=financeiro[String(o.numero)];return {id:o.id,cells:[<div key="n"><button className="com-link" onClick={()=>abrirPedido(o)}>#{o.numero}</button><small>{data(o.data)}</small></div>,<div key="c"><button className="com-link" onClick={()=>abrirCliente(clientes.find(c=>String(c.id)===String(o.clienteId))||{id:o.clienteId,nome:o.cliente})}>{o.cliente}</button><small>{o.vendedor||'Responsável não informado'}</small></div>,brl(o.centavos??valor(o.valor)),<span key="s" className={`com-signal ${sinal>0?'is-paid':''}`}>{!Number.isFinite(sinal)||sinal==null?'Não informado':sinal===0?'Sem sinal':brl(valor(sinal))}</span>,f?brl(valor(f.recebido)):'A conferir',f?brl(valor(f.saldo)):'A conferir',<button key="a" className="com-link" onClick={()=>abrirPedido(o)}>Consultar pedido</button>]};});}
 function abrirCliente(c){setModal({tipo:'cliente',c});}
 function abrirOrc(o){setModal({tipo:'orcamento',o});}
